import { createStep, createWorkflow } from '@mastra/core/workflows';
import { z } from 'zod';
import { PARTIAL_DATE } from '#lib/types.ts';
import type { Candidate, Inscription } from '#lib/types.ts';
import { runFailure } from './http.ts';
import { buildQuery, dropGated, resolveMatches } from './identity.ts';
import { search } from './search/serpapi.ts';

export const confidenceSchema = z.enum(['high', 'medium', 'low']);

export const partialDate = z.string().regex(PARTIAL_DATE);

export const inscriptionSchema = z.object({
	carvedName: z.string(),
	name: z.string().min(1),
	maidenName: z.string().nullable(),
	born: partialDate.nullable(),
	died: partialDate.nullable()
});

export const sourceSchema = z.object({
	id: z.string(),
	url: z.string().regex(/^https?:\/\//i),
	title: z.string(),
	site: z.string(),
	snippet: z.string()
});

const candidateSchema = z.object({
	name: z.string(),
	born: partialDate.nullable(),
	died: partialDate.nullable(),
	confidence: confidenceSchema,
	sources: z.array(sourceSchema)
});

const withRecords = z.object({ inscription: inscriptionSchema, records: z.array(sourceSchema) });

const searchStep = createStep({
	id: 'search',
	inputSchema: inscriptionSchema,
	outputSchema: withRecords,
	retries: 2,
	execute: async ({ inputData }) => ({
		inscription: inputData,
		records: dropGated(await search.search(buildQuery(inputData)))
	})
});

const resolveStep = createStep({
	id: 'resolve',
	inputSchema: withRecords,
	outputSchema: z.object({ candidates: z.array(candidateSchema) }),
	execute: ({ inputData }) =>
		Promise.resolve({
			candidates: resolveMatches(inputData.inscription, inputData.records)
		})
});

const researchWorkflow = createWorkflow({
	id: 'research',
	inputSchema: inscriptionSchema,
	outputSchema: z.object({ candidates: z.array(candidateSchema) })
})
	.then(searchStep)
	.then(resolveStep) // NOSONAR: Mastra builder .then(), not a Promise
	.commit();

/**
 * Searches for records about a stone's person and keeps the ones that match.
 * @param inscription The stone's person.
 * @returns Candidates, possibly empty.
 * @throws {ProviderError} When search fails after retries.
 */
export async function runResearch(inscription: Inscription): Promise<Candidate[]> {
	const run = await researchWorkflow.createRun();
	const result = await run.start({ inputData: inscription });
	if (result.status !== 'success') {
		throw runFailure('Research', result.status === 'failed' ? result.error : undefined);
	}
	return result.result.candidates;
}
import { serpApiKey } from '../env.ts';
import { ProviderError } from '../http.ts';
import type { SourceRecord } from '#lib/types.ts';
import type { SearchProvider } from './index.ts';

interface OrganicResult {
	link?: string;
	title?: string;
	snippet?: string;
}

interface Engine {
	engine: string;
	/** SerpApi names the query parameter differently per engine. */
	queryParam: string;
	extra?: Record<string, string>;
}

/** Engines that return organic results as link, title and snippet. Order sets the result order. */
const ENGINES: Engine[] = [
	{ engine: 'google', queryParam: 'q', extra: { num: '10', gl: 'us', hl: 'en' } },
	{ engine: 'bing', queryParam: 'q' },
	{ engine: 'yahoo', queryParam: 'p' },
	{ engine: 'duckduckgo', queryParam: 'q' },
	{ engine: 'yandex', queryParam: 'text' }
];

/**
 * Reduces a URL to a key shared by duplicates: no scheme, "www.", locale subdomain, query or hash.
 * @param link A result link.
 * @returns The dedupe key, or null when the link is not a web URL.
 */
export function canonicalUrl(link: string): string | null {
	const url = URL.parse(link);
	if (!url || !/^https?:$/.test(url.protocol)) return null;
	const host = url.hostname.toLowerCase().replace(/^www\./, '');
	// Find a Grave serves one memorial under many locale subdomains and slugs.
	const memorial =
		/^([a-z]{2}\.)?findagrave\.com$/.exec(host) && /\/memorial\/(\d+)/.exec(url.pathname);
	if (memorial) return `findagrave.com/memorial/${memorial[2]}`;
	return `${host}${url.pathname.replace(/\/+$/, '')}`;
}

/**
 * Runs one engine through SerpApi.
 * @param e Engine settings.
 * @param query Search query.
 * @returns The engine's organic results; none when it reports an empty result set.
 * @throws {Error} When the request fails.
 */
async function searchEngine(e: Engine, query: string): Promise<OrganicResult[]> {
	const url = new URL('https://serpapi.com/search.json');
	url.search = new URLSearchParams({
		engine: e.engine,
		[e.queryParam]: query,
		...e.extra,
		api_key: serpApiKey()
	}).toString();
	const res = await fetch(url, { signal: AbortSignal.timeout(20_000) });
	const body: { organic_results?: OrganicResult[]; error?: string } = await res.json();
	// SerpApi reports an empty result set as an error string.
	if (body.error?.includes("hasn't returned any results")) return [];
	if (!res.ok || body.error) throw new Error(body.error ?? `SerpApi ${res.status}`);
	return body.organic_results ?? [];
}

/** Web search through SerpApi: every engine in parallel, merged and deduplicated by URL. */
export class SerpApiProvider implements SearchProvider {
	/** @inheritdoc */
	async search(query: string): Promise<SourceRecord[]> {
		const settled = await Promise.allSettled(ENGINES.map((e) => searchEngine(e, query)));
		// One engine failing is normal; losing every engine is a provider failure.
		if (settled.every((r) => r.status === 'rejected')) {
			throw new ProviderError('Search failed', {
				cause: (settled[0] as PromiseRejectedResult).reason
			});
		}
		const records: SourceRecord[] = [];
		const seen = new Set<string>();
		for (const r of settled.flatMap((s) => (s.status === 'fulfilled' ? s.value : []))) {
			const key = r.link ? canonicalUrl(r.link) : null;
			if (!key || seen.has(key)) continue;
			seen.add(key);
			records.push({
				id: `s${records.length + 1}`,
				url: r.link!,
				title: r.title ?? '',
				site: URL.parse(r.link!)!.hostname,
				snippet: r.snippet ?? ''
			});
		}
		return records;
	}
}

export const search: SearchProvider = new SerpApiProvider();
- **Rejected**:
  - Multiple engines or providers: PRD Stretch.
  - A Find a Grave scraper: no API and terms restrict it. SerpApi results that link there are fine.
- **Interface**: `SearchProvider.search(query): Promise<SourceRecord[]>`, with one implementation (`serpapi.ts`).

## R6. Gated and paywalled sources

- **Decision**: A static deny-list of hostnames is applied to search results before identity matching: `ancestry.*`, `newspapers.com`, `genealogybank.com`, `myheritage.*`, `findmypast.*`, `newspaperarchive.com`, `fold3.com`. A page fetch that returns 401/402/403 or a login redirect drops that source.
- **Rationale**: PRD §6 excludes paywalled and login-gated sources. A static list covers the big genealogy paywalls, and the fetch check catches the rest.
- **Rejected**: Detecting paywalls by page content, which is too fuzzy for a deterministic rule.

## R7. Identity resolution

- **Decision**:
  1. The model picks the search results that are about the stone's person (`pickMatches`, temperature 0). Per picked result it returns `{ id, born, died, place, confidence }`.
  2. Code (`resolveMatches`) then:
     - drops unknown ids;
     - keeps only results whose title or snippet names the surname as a whole word (generational suffixes Jr, Sr, II, III, IV, V are ignored);
     - drops picks whose stated years conflict with the inscription (a `?` digit matches any digit);
     - keeps a date only if the picked result itself states that year;
     - builds one candidate, with the inscription's name and all kept results as sources, or no candidate when nothing is left.
  3. Candidate `confidence` is the best of the picks. The model's `high` is capped at `medium` when no picked result states a year.
  4. The visitor always confirms, even for the single candidate, and sees the confidence. A `low` confidence tells them to check the sources.
- **Rationale**: Deciding which snippets are about the stone's person is model work. The surname, date-conflict and date-attribution rules are deterministic and testable (Constitution III). The model no longer clusters people, so there is nothing to merge.
- **Tradeoff**: A namesake whose snippet states no dates can still be picked. The confirm step and the visible source links are the safeguard.
- **Rejected**: Pure string scoring, which can't tell two "John Smith 1950–2011" obituaries apart by snippet alone; having the model group results into several people, which let one result attach to the wrong person.

## R8. Story grounding (fetch page text)

- **Decision**: After confirmation, the story pipeline:
  1. Fetches the candidate's source pages in memory, at most 5 in parallel with an 8 s timeout and a 2 MB cap each.
| `site`    | string | Hostname, used for display and the deny-list.     |
| `snippet` | string | Used for matching; shown as a short preview only. |

## Candidate

The person the match step picked records for (`identity.ts` output). At most one per response.

| Field        | Type                          | Rule                                                                             |
| ------------ | ----------------------------- | -------------------------------------------------------------------------------- |
| `name`       | string                        | The Inscription's name.                                                          |
| `born`       | PartialDate \| null           | Kept only if a picked result states that year.                                   |
| `died`       | PartialDate \| null           | Kept only if a picked result states that year; must not conflict with the stone. |
| `place`      | string \| null                |                                                                                  |
| `confidence` | `'high' \| 'medium' \| 'low'` | Best of the picks; `high` is capped at `medium` when no pick states a year.      |
| `sources`    | SourceRecord[]                | Length ≥ 1. Every picked result that names the surname and does not conflict.    |

## Story

A union:

- `{ status: 'told', paragraph: string, sources: SourceRecord[] }`: one spoken first-person paragraph. `sources` holds only the sources of facts the paragraph uses.
- `{ status: 'insufficient' }`: the client then shows the Epitaph.

- Facts (`claim`, `sourceId`, `quote`) are server-only and never sent to the client. A fact survives only if its quote is found verbatim in its cited source's text.
- Sentences that add a number, a proper noun or a negation the verified facts do not give are dropped before the paragraph is returned.

